  @override
  String get adderallMilestone1Title => 'Erste 24 Stunden: Auszahlung beginnt';

  @override
  String get adderallMilestone1Description =>
      'Sie können eine erhöhte Müdigkeit, Depression und Appetit verspüren, wenn sich Ihr Körper an das Leben ohne Stimulanzien anpasst. Das ist normal und vorübergehend. Bleiben Sie hydratisiert und ruhen Sie sich aus, wenn Sie es brauchen.';

  @override
  String get adderallMilestone3Title => 'Tag 3: Spitzenrücknahme';

  @override
  String get adderallMilestone3Description =>
      'Entzugserscheinungen erreichen ihre höchste Intensität. Sie können starke Müdigkeit, Reizbarkeit und Konzentrationsschwierigkeiten erleben. Das ist der schwierigste Teil - aber von hier aus wird es besser. Erwägen Sie, sich an Ihr Support-System zu wenden.';

  @override
  String get adderallMilestone7Title =>
      'Eine Woche: Körperliche Symptome verbessern';

  @override
  String get adderallMilestone7Description =>
      'Die schlimmsten körperlichen Entzugserscheinungen beginnen zu verblassen. Schlafmuster beginnen sich zu normalisieren und das Energieniveau verbessert sich langsam. Ihr Körper passt sich an das Funktionieren ohne Stimulanzien an.';

  @override
  String get adderallMilestone14Title =>
      'Zwei Wochen: Emotionale Stabilität kehrt zurück';

  @override
  String get adderallMilestone14Description =>
      'Stimmungsschwankungen und Reizbarkeit verringern sich. Sie gewinnen das emotionale Gleichgewicht wieder, während sich Ihre Gehirnchemie stabilisiert. Viele Menschen finden diese Woche markiert einen Wendepunkt in ihrer Erholung Reise.';

  @override
  String get adderallMilestone30Title =>
      'Ein Monat: Brain Chemistry Rebalancing';

  @override
  String get adderallMilestone30Description =>
      'Dein Gehirn heilt aktiv. Die natürliche Dopaminproduktion verbessert sich, und Sie können eine bessere Konzentration und Motivation ohne Medikamente bemerken. Schlafqualität und Appetit kehren zu normalen Mustern zurück.';

  @override
  String get adderallMilestone60Title =>
      'Zwei Monate: Denken und Gedächtnis verbessern';

  @override
  String get adderallMilestone60Description =>
      'Signifikante Verbesserungen der mentalen Klarheit, des Gedächtnisses und der Stimmungsstabilität. Das Belohnungssystem Ihres Gehirns heilt und macht alltägliche Aktivitäten auf natürliche Weise lohnender. Viele Menschen berichten, dass sie sich mehr wie sie selbst fühlen.';

  @override
  String get adderallMilestone90Title =>
      'Drei Monate: Meilenstein der großen Erholung';

  @override
  String get adderallMilestone90Description =>
      'Die meisten Entzugserscheinungen sind behoben. Dein Gehirn hat erhebliche Fortschritte bei der Heilung gemacht. Natürliche Energieniveaus, Fokus und emotionale Regulierung werden deutlich verbessert. Das ist eine große Errungenschaft, die es wert ist, gefeiert zu werden.';

  @override
  String get adderallMilestone180Title =>
      'Sechs Monate: Gehirnheilung geht weiter';

  @override
  String get adderallMilestone180Description =>
      'Die Dopamin-Signalisierung erholt sich weiter. Fokus, Gedächtnis, Stimmung und tägliche Lebensqualität verbessern sich weiter.';

  @override
  String get adderallMilestone365Title =>
      'Ein Jahr: Beinahe vollständige Erholung';

  @override
  String get adderallMilestone365Description =>
      'Das Dopaminsystem Ihres Gehirns hat sich weitgehend wieder normalisiert. Sie haben Ihre Widerstandsfähigkeit bewiesen und Ihr Leben ohne Abhängigkeit von Stimulanzien wieder aufgebaut. Dieser Meilenstein stellt eine vollständige Transformation dar - feiern Sie, wie weit Sie gekommen sind!';

