  @override
  String get benzoMilestone7Title => 'Frühe Rücknahmephase';

  @override
  String get benzoMilestone7Description =>
      'Nach Abschluss einer allmählichen Verjüngung können frühe Entzugserscheinungen wie Rebound-Angst und Schlaflosigkeit auftreten. Dies ist dein Nervensystem, das anfängt, sich neu zu justieren. Medizinische Unterstützung in dieser Phase ist entscheidend für Sicherheit und Komfort.';

  @override
  String get benzoMilestone14Title => 'Akute Entzugsspitze';

  @override
  String get benzoMilestone14Description =>
      'Akute Entzugserscheinungen erreichen typischerweise innerhalb der ersten zwei Wochen ihren Höhepunkt. Sie können Angst, Schlafstörungen und körperliche Beschwerden erleben. Diese Symptome zeigen, während herausfordernd, Ihr Gehirn beginnt zu heilen und wieder auszugleichen.';

  @override
  String get benzoMilestone60Title => 'Schlafarchitektur verbessert';

  @override
  String get benzoMilestone60Description =>
      'Studien zeigen, dass sich Ihre natürlichen Schlafmuster nach 2 Monaten wieder erholen. Langsamwelliger Schlaf nimmt zu und die Schlafqualität verbessert sich im Vergleich zur Einnahme von Benzodiazepinen, obwohl sich die Gesamtschlafeffizienz möglicherweise noch erholt.';

  @override
  String get benzoMilestone90Title => 'Körperliche Gesundheit stabilisiert';

  @override
  String get benzoMilestone90Description =>
      'Rund 3 Monate haben sich viele körperliche Entzugserscheinungen signifikant verbessert. Ihr Körper passt sich weiterhin an das Funktionieren ohne Medikamente an. Angst und Stimmung können immer noch schwanken, aber die Gesamtfunktion verbessert sich.';

  @override
  String get benzoMilestone180Title =>
      'Denken und Gedächtnis beginnen sich zu erholen';

  @override
  String get benzoMilestone180Description =>
      'Nach sechs Monaten zeigen Gedächtnis und Aufmerksamkeit eine messbare Verbesserung. Die Forschung findet Erholung in vielen Denkfähigkeiten, mit Gewinnen, die über sechs Monate hinausgehen.';

  @override
  String get benzoMilestone365Title => 'Ein Jahr Heilung';

  @override
  String get benzoMilestone365Description =>
      'Nach einem Jahr zeigen sich deutliche Verbesserungen des geistigen und körperlichen Wohlbefindens. Viele berichten von einer reduzierten Angst, einer besseren Schlafqualität und einer verbesserten allgemeinen Gesundheit im Vergleich zur langfristigen Einnahme von Benzodiazepinen. Die Gehirnheilung geht weiter.';

  @override
  String get benzoMilestone540Title => 'Fortsetzung der Brain Recovery';

  @override
  String get benzoMilestone540Description =>
      'Nach 18 Monaten verbessern sich Gedächtnis, Aufmerksamkeit und klares Denken weiter. Das beruhigende GABA-System des Gehirns hatte weit über ein Jahr Zeit, sich zu beruhigen, während das Gehirn weiterhin gesündere Muster aufbaut.';

  @override
  String get benzoMilestone730Title => 'Zwei Jahre: Große Fortschritte';

  @override
  String get benzoMilestone730Description =>
      'Zwei Jahre markieren eine deutliche Erholung. Die meisten Menschen haben viel klareres Denken, stabilere Emotionen und eine viel bessere Lebensqualität als bei der langfristigen Verwendung von Benzodiazepin.';

  @override
  String get benzoMilestone1095Title => 'Drei Jahre: Langfristige Erholung';

  @override
  String get benzoMilestone1095Description =>
      'Mit drei Jahren liegt die lange Widerrufsfrist weit hinter den meisten Menschen. Schlaf, Stimmung, Gedächtnis und Aufmerksamkeit mussten sich jahrelang erholen, und das tägliche Leben ist in der Regel viel besser als bei langfristiger Nutzung.';

