  @override
  String get methMilestone1Description =>
      'Die erste Crash-Phase beginnt mit tiefer Müdigkeit und erhöhtem Appetit, wenn sich Ihr Körper erholt. Sie können Depressionen erleben und stark schlafen, wenn sich Ihr System durch die intensive Stimulation zu stabilisieren beginnt.';

  @override
  String get methMilestone3Title => 'Tag 3 - Peak Rückzug';

  @override
  String get methMilestone3Description =>
      'Das Verlangen intensiviert sich in dieser Zeit erheblich, wenn sich Ihr Körper anpasst. Sie können im Vergleich zur Crash-Phase eine erhöhte Energie erfahren, die das Verlangen stärker machen kann. Dies ist eine kritische Zeit für Rückfallprävention und Unterstützung.';

  @override
  String get methMilestone7Title =>
      'Eine Woche - Körperliche Symptome Leichtigkeit';

  @override
  String get methMilestone7Description =>
      'Akute Entzugserscheinungen beginnen nachzulassen, obwohl psychologische Herausforderungen bestehen bleiben. Ihre Schlafmuster beginnen sich zu normalisieren und körperliche Beschwerden nehmen ab. Dies markiert den Übergang vom akuten zum postakuten Rückzug.';

  @override
  String get methMilestone30Title => 'Ein Monat - Emerging Stability';

  @override
  String get methMilestone30Description =>
      'Die Flitterwochenphase beginnt, wenn Ihr Körper heilt und das Verlangen zu verblassen beginnt. Das Energieniveau steigt und die Stimmung verbessert sich, wenn die Chemie des Gehirns beginnt, sich neu auszubalancieren. Bleiben Sie jedoch wachsam, da sich noch Herausforderungen ergeben können.';

  @override
  String get methMilestone90Title => 'Drei Monate - Gehirnheilung beginnt';

  @override
  String get methMilestone90Description =>
      'Ihr Gehirn erholt sich aktiv. Aufmerksamkeit, Gedächtnis und Entscheidungsfindung beginnen sich besser zu fühlen, wenn sich das Belohnungssystem in Richtung Normalität bewegt.';

  @override
  String get methMilestone180Title => 'Sechs Monate - kardiovaskuläre Erholung';

  @override
  String get methMilestone180Description =>
      'Die Herzfunktion zeigt eine messbare Verbesserung bei Abstinenz. Studien zeigen, dass sich die Herzfunktion in diesem Zeitraum in Kombination mit medizinischer Unterstützung signifikant erholen kann. Blutdruck und Herzrhythmus stabilisieren sich weiter.';

  @override
  String get methMilestone365Title => 'Ein Jahr - Major Brain Recovery';

  @override
  String get methMilestone365Description =>
      'Nach einem Jahr hat das Dopaminsystem große Gewinne gemacht. Natürliche Belohnungen fühlen sich wieder lohnender an, während Stimmung, Gedächtnis und Entscheidungsfindung deutlich besser sind.';

  @override
  String get methMilestone420Title => '14 Monate - Dopamin-Normalisierung';

  @override
  String get methMilestone420Description =>
      'Gehirn-scans zeigen Dopamin-recycling-Proteine nähert sich gesunden Ebenen um dieses Stadium. Gedächtnis, Motivation und die Fähigkeit, alltägliche Aktivitäten zu genießen, verbessern sich weiter.';

  @override
  String get methMilestone730Title => 'Zwei Jahre - Nachhaltige Erholung';

  @override
  String get methMilestone730Description =>
      'Zwei Jahre ohne Meth geben dem Gehirn nachhaltige Zeit zur Heilung. Aufmerksamkeit, Stimmung, Gedächtnis und die tägliche Lebensqualität verbessern sich weiter.';

