  @override
  String get nitrousOxideMilestone1Title =>
      'Erste 24 Stunden - System Clearing';

  @override
  String get nitrousOxideMilestone1Description =>
      'Das Gas verlässt Ihr System innerhalb von Minuten, aber die Heilung dauert länger. Schwindel beruhigt sich, Kopfschmerzen lindern sich und Ihr Gehirn beginnt sich ohne Dopaminabkürzung anzupassen. Ihre B12-Wiederherstellung beginnt jetzt.';

  @override
  String get nitrousOxideMilestone3Title => 'Tag 3 - Kein physischer Rückzug';

  @override
  String get nitrousOxideMilestone3Description =>
      'Hier sind gute Nachrichten: Lachgas verursacht keinen physischen Entzug. Die Triebe, die Sie fühlen, sind psychologisch - Gewohnheit und Assoziation, nicht Ihr Körper, der eine Substanz fordert. Das macht sie überschaubar.';

  @override
  String get nitrousOxideMilestone7Title => 'Eine Woche - B12 Rising';

  @override
  String get nitrousOxideMilestone7Description =>
      'Eine Woche, in der kein neues B12 zerstört wurde. Wenn Sie mit der Ergänzung begonnen haben, steigen Ihre Level bereits. Energie, Stimmung und Fokus sind alle an B12 gebunden - Sie sollten anfangen zu fühlen, dass sie sich verbessern.';

  @override
  String get nitrousOxideMilestone14Title => 'Zwei Wochen - Nervenheilung';

  @override
  String get nitrousOxideMilestone14Description =>
      'B12 ist wichtig für die schützende Beschichtung Ihrer Nervenfasern. Zwei Wochen später ist dieser Reparaturprozess aktiv im Gange. Jedes Kribbeln oder Taubheitsgefühl, das Sie hatten, sollte lindern - Ihr Nervensystem flickt sich wieder zusammen.';

  @override
  String get nitrousOxideMilestone30Title => 'Ein Monat - Energierückkehr';

  @override
  String get nitrousOxideMilestone30Description =>
      'B12 spielt eine Schlüsselrolle bei der Produktion roter Blutkörperchen, was bedeutet, dass jede Zelle in Ihrem Körper mit Sauerstoff versorgt wird. Ein Monat Erholung und Ergänzung bedeutet sinnvoll bessere Energie, klareres Denken und eine stabilere Stimmung.';

  @override
  String get nitrousOxideMilestone90Title =>
      'Drei Monate - Neurologische Erholung';

  @override
  String get nitrousOxideMilestone90Description =>
      'Drei Monate ohne B12 Zerstörung bedeutet drei Monate Nervenreparatur. Das Nervensystem ist belastbar - die meisten Menschen, die mit der Behandlung begonnen haben, sehen zu diesem Zeitpunkt eine signifikante Erholung in Kribbeln, Schwäche und Gehirnnebel.';

  @override
  String get nitrousOxideMilestone365Title =>
      'Ein Jahr - Langfristige Gesundheit gesichert';

  @override
  String get nitrousOxideMilestone365Description =>
      'Ein ganzes Jahr frei von Lachgas. Ihre B12-Läden sind wiederhergestellt, Ihr Nervensystem hatte ein Jahr Zeit zu heilen, und das kardiovaskuläre Risiko durch erhöhtes Homocystein ist verschwunden. Dein Körper arbeitet wieder an seiner eigenen Chemie.';

