  @override
  String get cocaineMilestone14Title => 'Zwei Wochen - Stabilität finden';

  @override
  String get cocaineMilestone14Description =>
      'Viele Menschen fühlen sich emotional stabiler. Ihre Energieniveaus verbessern sich und akute Entzugserscheinungen lindern sich. Ihre kardiovaskuläre Gesundheit verbessert sich weiterhin erheblich.';

  @override
  String get cocaineMilestone60Title =>
      'Zwei Monate - Schlaf und Stimmung verbessern';

  @override
  String get cocaineMilestone60Description =>
      'Ihre Schlafqualität ist merklich besser, da sich Ihre Gehirnchemie weiter normalisiert. Möglicherweise fühlen Sie sich ausgeruhter und erleben während des Tages stabilere Stimmungen.';

  @override
  String get cocaineMilestone90Title =>
      'Drei Monate - Wiederherstellung des Gehirns';

  @override
  String get cocaineMilestone90Description =>
      'Ihr Dopamin-System erholt sich. Fokus, Entscheidungsfindung und emotionale Kontrolle sind deutlich besser und das Denken ist klarer.';

  @override
  String get cocaineMilestone180Title => 'Sechs Monate - klareres Denken';

  @override
  String get cocaineMilestone180Description =>
      'Gehirnscans zeigen Erholung in der Vorderseite des Gehirns, dem Bereich, der die Planung und Selbstkontrolle unterstützt. Gedächtnis, Impulskontrolle und klares Denken verstärken sich weiter.';

  @override
  String get cocaineMilestone365Title => 'Ein Jahr - Herz-Kreislauf-Gesundheit';

  @override
  String get cocaineMilestone365Description =>
      'Ihr Herz und Herz-Kreislauf-System haben sich bemerkenswert erholt. Blutdruck und Herzfrequenz werden normalisiert. Das Risiko von Herzinfarkt und Schlaganfall ist signifikant gesunken. Dein Körper heilt.';

  @override
  String get cocaineMilestone730Title => 'Zwei Jahre - Nachhaltige Erholung';

  @override
  String get cocaineMilestone730Description =>
      'Die Gehirnheilung setzt sich mit anhaltenden Verbesserungen des Gedächtnisses, des Fokus und der emotionalen Regulierung fort. Ihre Nervenbahnen haben sich erheblich neu organisiert und unterstützen gesündere Muster und ein besseres allgemeines Wohlbefinden.';

