  @override
  String get alcoholMilestone1Title =>
      'Schlafqualität beginnt sich zu verbessern';

  @override
  String get alcoholMilestone1Description =>
      'Ihre REM-Schlafzyklen beginnen sich innerhalb des ersten Tages zu normalisieren. Während Alkohol Ihnen beim Einschlafen helfen kann, stört er den Tiefschlaf und die REM-Zyklen während der Nacht und verursacht fragmentierten Schlaf.';

  @override
  String get alcoholMilestone3Title => 'Hydratation Ebenen wiederherstellen';

  @override
  String get alcoholMilestone3Description =>
      'Ihre Nieren erholen sich von den harntreibenden Wirkungen von Alkohol. Alkohol unterdrückt antidiuretisches Hormon, was zu erhöhtem Wasserlassen und Dehydrierung führt. Am Tag 3 verbessert sich der Flüssigkeitshaushalt Ihres Körpers erheblich.';

  @override
  String get alcoholMilestone7Title => 'Immunsystem stärkt sich';

  @override
  String get alcoholMilestone7Description =>
      'Ihre weißen Blutkörperchen erholen ihre Funktion. Selbst ein einziger Anfall von starkem Trinken kann die Immunfunktion für bis zu 24 Stunden beeinträchtigen, und chronisches Trinken schwächt die Fähigkeit Ihres Körpers, Infektionen zu bekämpfen, erheblich.';

  @override
  String get alcoholMilestone14Title => 'Brain Volume Recovery beginnt';

  @override
  String get alcoholMilestone14Description =>
      'Das Gehirnvolumen beginnt sich innerhalb der ersten zwei Wochen zu erholen. Denken und Gedächtnis verbessern sich in den folgenden Monaten weiter.';

  @override
  String get alcoholMilestone30Title => 'Blutdruck normalisiert sich';

  @override
  String get alcoholMilestone30Description =>
      'Ihr Herz-Kreislauf-System zeigt eine signifikante Verbesserung. Regelmäßiger Alkoholkonsum erhöht den Blutdruck, aber Abstinenz für etwa einen Monat kann dazu beitragen, den Blutdruck wieder auf ein gesünderes Niveau zu bringen.';

  @override
  String get alcoholMilestone60Title => 'Leberfunktion verbessert';

  @override
  String get alcoholMilestone60Description =>
      'Ihre Leber zeigt eine messbare Verbesserung der Funktion. Dieses regenerative Organ kann sich signifikant von alkoholbedingten Schäden erholen, wobei Leberenzyme und Fettansammlung innerhalb von 2 Monaten nach Abstinenz eine Verbesserung zeigen.';

  @override
  String get alcoholMilestone90Title =>
      'Denken und Gedächtnis verbessern sich erheblich';

  @override
  String get alcoholMilestone90Description =>
      'Die ersten drei Monate bringen große Gewinne in Gedächtnis, Konzentration und Entscheidungsfindung, mit Erholung in den folgenden Monaten fortgesetzt.';

  @override
  String get alcoholMilestone180Title =>
      'Gehirnvolumen und Funktion Continue Recovery';

  @override
  String get alcoholMilestone180Description =>
      'Sechs Monate nüchtern geben dem Gehirn nachhaltige Zeit, sich zu erholen. Gehirnvolumen und Denkfähigkeiten verbessern sich weiter.';

  @override
  String get alcoholMilestone365Title => 'Krebsrisikoreduktion kann beginnen';

  @override
  String get alcoholMilestone365Description =>
      'Ein Jahr Abstinenz kann beginnen, das Krebsrisiko zu reduzieren. Während Alkohol das Risiko für mehrere Krebsarten (Leber, Brust, Kolorektal, Speiseröhre) deutlich erhöht, zeichnet sich die Forschung zur Risikoreduktion noch ab und variiert je nach Krebsart.';

  @override
  String get smokingMilestone1Title => 'Kläranlagen für Kohlenmonoxid';

