      'Sie stehen vor dem Sturm frontal! Körperliche Entzugserscheinungen erreichen normalerweise den Höhepunkt um Tag 3 für viele Substanzen, einschließlich Angst, Stimmungsschwankungen und körperliche Beschwerden. Das bedeutet, dass du durch den schwierigsten Teil kommst.';

  @override
  String get customMilestone7Title => 'Akute Entzugsphase Ende';

  @override
  String get customMilestone7Description =>
      'Das Schlimmste liegt hinter dir! Nach einer Woche beginnen akute Entzugserscheinungen für die meisten Substanzen abzuklingen. Ihr Körper passt sich an seine neue Normalität an und beginnt sich zu stabilisieren.';

  @override
  String get customMilestone14Title => 'Frühe Erholung Stabilisierung';

  @override
  String get customMilestone14Description =>
      'Dein Verstand klärt! Zwei wochen nüchternheit bringen oft eine verbesserte geistige klarheit und reduziertes verlangen, wenn sich ihr gehirn an das funktionieren ohne süchtig machende substanzen anpasst.';

  @override
  String get customMilestone30Title => 'Ein Monat Meilenstein';

  @override
  String get customMilestone30Description =>
      'Ein großer Sieg! Dreißig Tage Nüchternheit bedeuten einen bedeutenden Fortschritt. Viele Menschen finden, dass sich Schlafmuster, Stimmung und Energieniveaus während dieser Zeit weiter verbessern.';

  @override
  String get customMilestone90Title => 'Dreimonatiger Erholungs-Meilenstein';

  @override
  String get customMilestone90Description =>
      'Ihr Engagement zahlt sich aus! Drei Monate Erholung stellen eine bedeutende Errungenschaft dar. Postakute Entzugserscheinungen beginnen typischerweise zu verblassen, und viele Menschen berichten, dass sie sich wieder wie sie selbst fühlen.';

  @override
  String get customMilestone180Title => 'Sechs Monate Recovery Achievement';

  @override
  String get customMilestone180Description =>
      'Du baust dauerhafte Veränderungen auf! Sechs Monate Nüchternheit bringen oft kontinuierliche Verbesserungen der körperlichen Gesundheit, der emotionalen Stabilität und der allgemeinen Lebensqualität, wenn Ihr Körper weiter heilt.';

  @override
  String get customMilestone365Title => 'Ein Jahr Erholung';

  @override
  String get customMilestone365Description =>
      'Eine unglaubliche Leistung! Ein Jahr Nüchternheit ist ein wichtiger Meilenstein im Leben. Viele Menschen erleben zu diesem Zeitpunkt signifikante Verbesserungen in der körperlichen Gesundheit, den Beziehungen und dem allgemeinen Wohlbefinden.';

  @override
  String get customMilestone730Title => 'Zwei Jahre anhaltende Erholung';

  @override
  String get customMilestone730Description =>
      'Du hast dir ein neues Leben aufgebaut! Zwei Jahre Erholung zeigen bemerkenswerte Widerstandsfähigkeit und Engagement. Langfristige Nüchternheit bringt oft tiefgreifende positive Veränderungen in allen Bereichen des Lebens und deutlich reduziertes Risiko eines Rückfalls.';

  @override
  String get addictionSsri => 'SSRI';

  @override
  String get ssriPageTitle => 'SSRI Erholung';

  @override
  String get ssriHeaderStarted => 'Ihre Recovery Journey';

  @override
  String get ssriHeaderNotStarted => 'Vorteile von Tapering Off SSRIs';

  @override
  String get ssriSubtitleStarted =>
      'Verfolgen Sie Ihre Fortschritte und feiern Sie jeden Meilenstein';

  @override
  String get ssriSubtitleNotStarted =>
      'Sehen Sie, was passiert, wenn Sie sich verjüngen';

  @override
  String get ssriMilestone3Title => 'Tag 3: FINISH Syndrome Peaks';

  @override
  String get ssriMilestone3Description =>
      'Entzugserscheinungen erreichen oft den Höhepunkt der Tage 2-4. SSRIs ändern, wie Serotonin recycelt wird, so dass das Gehirn Zeit braucht, um sich anzupassen, nachdem Sie aufhören. Erwarten Sie grippeähnliche Symptome, Schwindel, Schlaflosigkeit, Übelkeit und \"Gehirn-Zaps\". Paroxetin neigt dazu, einen stärkeren Entzug zu verursachen; Fluoxetin hält viel länger im Körper und ist normalerweise milder.';

  @override
  String get ssriMilestone7Title =>
      'Eine Woche: Akute Phase beginnt zu erleichtern';

  @override
  String get ssriMilestone7Description =>
      'Die intensivsten körperlichen Symptome beginnen zu sinken. Ihr Gehirn passt seine Serotonin-Signalisierung an, um ohne das Medikament zu funktionieren. Schlaf und Appetit beginnen sich zu stabilisieren.';

  @override
  String get ssriMilestone14Title => 'Zwei Wochen: Körperliche Symptome lösen';

  @override
  String get ssriMilestone14Description =>
      'Die meisten akuten körperlichen Abbruchsymptome haben sich signifikant reduziert oder gelöst. Brain Zaps, Übelkeit und Schwindel verblassen. Emotionale Empfindlichkeit kann immer noch erhöht werden, wenn Ihr Gehirn weiterhin sein Serotoninsystem ausgleicht.';

  @override
  String get ssriMilestone30Title =>
      'Ein Monat: Stimmung und Energie stabilisieren';

  @override
  String get ssriMilestone30Description =>
      'Ein Monat ist ein wichtiger Meilenstein. Die Schlafqualität verbessert sich, das Energieniveau stabilisiert sich und viele Menschen bemerken, dass ihre Stimmung beginnt, ein neues Gleichgewicht zu finden. Das Gehirn stellt aktiv seine natürliche Serotoninregulation wieder her.';

  @override
  String get ssriMilestone90Title => 'Drei Monate: Serotonin-Rezeptor Erholung';

  @override
  String get ssriMilestone90Description =>
      'Drei Monate sind ein wichtiger Meilenstein der Erholung. Das Serotonin-System hatte Monate Zeit, sich anzupassen, nachdem das Medikament verschwunden war. Stimmung, Angst, Fokus und klares Denken sind für die meisten Menschen sinnvoll besser.';

  @override
  String get ssriMilestone180Title =>
      'Sechs Monate: Langfristige Gehirnanpassung';

  @override
  String get ssriMilestone180Description =>
      'Sechs Monate ermöglichen eine erhebliche neurologische Anpassung. Die Serotoninsysteme des Gehirns haben ihr natürliches Gleichgewicht gefunden. Viele Menschen berichten von einer verbesserten emotionalen Reichweite und für diejenigen, die es erlebt haben, hat sich die sexuelle Dysfunktion, die durch SSRIs verursacht wird, typischerweise aufgelöst.';

  @override
  String get ssriMilestone365Title => 'Ein Jahr: Erholung erreicht';

  @override
  String get ssriMilestone365Description =>
      'Ein Jahr markiert einen vollständigen Zyklus der Erholung. Die Forschung zeigt, dass die Mehrheit, die eine allmähliche Verjüngung abgeschlossen und psychologische Unterstützung erhalten hat, nach einem Jahr gut bleibt, wobei die Lebensqualität vergleichbar oder besser ist als diejenigen, die Medikamente einnahmen.';

  @override
  String get settingsShowSsriTracking => 'SSRI Tracking anzeigen';

  @override
  String get settingsNotifySsri => 'Benachrichtigen SSRI beenden Fortschritte';

  @override
  String get addictionSnri => 'SNRI';

  @override
  String get snriPageTitle => 'SNRI-Rückgewinnung';

  @override
  String get snriHeaderStarted => 'Ihre Recovery Journey';

  @override
  String get snriHeaderNotStarted => 'Vorteile von Tapering Off SNRIs';

  @override
  String get snriSubtitleStarted =>
      'Verfolgen Sie Ihre Fortschritte und feiern Sie jeden Meilenstein';

  @override
  String get snriSubtitleNotStarted =>
      'Sehen Sie, was passiert, wenn Sie sich verjüngen';

  @override
  String get snriMilestone3Title =>
      'Tag 3: Intensive Diskontinuationssyndromspitzen';

  @override
  String get snriMilestone3Description =>
      'SNRIs - insbesondere Venlafaxin (Effexor) - sind mit einigen der schwersten Antidepressiva-Abbruchssyndromen verbunden. Die sehr kurze Halbwertszeit von Venlafaxin (5 Stunden) bedeutet, dass die Symptome intensiver sein können als bei den meisten SSRIs. FINISH Symptome (Grippe-ähnliche Gefühle, Schlaflosigkeit, Übelkeit, Ungleichgewicht, sensorische Störungen, Hyperarousal) beeinflussen sowohl Serotonin und Noradrenalin-Systeme gleichzeitig.';

  @override
  String get snriMilestone7Title =>
      'Eine Woche: Zwei gehirnchemische Systeme passen sich an';

  @override
  String get snriMilestone7Description =>
      'SNRIs beeinflussen sowohl Serotonin und Noradrenalin-Wiederaufnahme. Beide Systeme passen sich gleichzeitig an. Die intensivsten körperlichen Symptome beginnen zu sinken, aber der duale Mechanismus bedeutet, dass sich die Anpassung komplexer anfühlen kann als bei SSRIs allein.';

  @override
  String get snriMilestone14Title =>
      'Zwei Wochen: Körperliche Symptome verblassen';

  @override
  String get snriMilestone14Description =>
      'Die meisten akuten körperlichen Absetzen Symptome haben deutlich reduziert. Brain Zaps, Übelkeit und Schwindel verblassen. Die Neujustierung des Noradrenalinsystems kann immer noch einige Angst- oder Blutdruckschwankungen verursachen - diese lösen sich typischerweise in den kommenden Wochen auf.';

  @override
  String get snriMilestone30Title =>
      'Ein Monat: Noradrenalin-System stabilisiert';

  @override
  String get snriMilestone30Description =>
      'Ein Monat ist ein wichtiger Meilenstein. Sowohl Serotonin- als auch Noradrenalinsysteme balancieren aktiv. Die Schlafqualität und das Energieniveau stabilisieren sich. Viele Menschen bemerken eine verbesserte emotionale Reichweite, wenn sich die Wirkung des Medikaments auf die emotionale Abstumpfung zu lösen beginnt.';

  @override
  String get snriMilestone90Title => 'Drei Monate: Dual System Rebalancing';

  @override
  String get snriMilestone90Description =>
      'Drei Monate sind ein wichtiger Meilenstein der Erholung. Das Serotonin- und Noradrenalinsystem hatte Monate Zeit, sich anzupassen. Stimmung, Angst, Fokus und klares Denken sind nach einem überwachten Taper sinnvoll besser.';

  @override
  String get snriMilestone180Title => 'Sechs Monate: Neurologische Erholung';

  @override
  String get snriMilestone180Description =>
      'Sechs Monate ermöglichen eine erhebliche Neujustierung des Serotonin- und Noradrenalinsystems. Die HPA-Achse - die SNRIs durch Noradrenalin beeinflussen - normalisiert sich. Viele Menschen berichten von einer deutlich verbesserten Widerstandsfähigkeit gegenüber alltäglichen Stressoren an dieser Stelle.';

  @override
  String get snriMilestone365Title => 'Ein Jahr: Erholung erreicht';

  @override
  String get snriMilestone365Description =>
      'Ein Jahr markiert einen vollständigen Zyklus der doppelten Serotonin-Norepinephrin-Wiederherstellung. Die Forschung zeigt konsequent, dass Menschen, die SNRIs unter medizinischer Aufsicht und mit psychologischer Unterstützung erfolgreich absetzen, nach einem Jahr gute Ergebnisse erzielen.';

  @override
  String get settingsShowSnriTracking => 'SNRI Tracking anzeigen';

  @override
  String get settingsNotifySnri =>
      'Benachrichtigen Sie SNRI, den Fortschritt zu beenden';

  @override
  String get addictionTca => 'Trizyklische Antidepressiva';

  @override
  String get tcaPageTitle => 'TCA-Rückgewinnung';

  @override
  String get tcaHeaderStarted => 'Ihre Recovery Journey';

  @override
  String get tcaHeaderNotStarted => 'Vorteile von Tapering Off TCAs';

  @override
  String get tcaSubtitleStarted =>
      'Verfolgen Sie Ihre Fortschritte und feiern Sie jeden Meilenstein';

  @override
  String get tcaSubtitleNotStarted =>
      'Sehen Sie, was passiert, wenn Sie sich verjüngen';

  @override
  String get tcaMilestone3Title => 'Tag 3: Acetylcholin Rebound Peaks';

  @override
  String get tcaMilestone3Description =>
      'TCAs blockieren Acetylcholin. Nach dem Anhalten kann dieses System kurzzeitig überaktiv werden. Zu den Symptomen gehören Übelkeit, Durchfall, Magenkrämpfe, starkes Schwitzen, Kopfschmerzen, Muskelschmerzen und Schlaflosigkeit. Diese Symptome in der Regel Peak früh und dann erleichtern.';

  @override
  String get tcaMilestone7Title => 'Eine Woche: Rebound Symptome Lockerung';

  @override
  String get tcaMilestone7Description =>
      'Der Acetylcholin-Rebound erreicht normalerweise in den ersten Tagen seinen Höhepunkt und beginnt sich um eine Woche zu entspannen. Magensymptome, Schwitzen und grippeähnliche Gefühle reduzieren sich, während die Körpersysteme, die Herzfrequenz, Verdauung und Schwitzen kontrollieren, wieder normal werden.';

  @override
  String get tcaMilestone14Title =>
      'Zwei Wochen: Anticholinerge Effekte Reversing';

  @override
  String get tcaMilestone14Description =>
      'Der trockene Mund, Verstopfung, Probleme beim Wasserlassen und verschwommenes Sehen, die durch TCAs verursacht werden, kehren sich um, wenn sich das Acetylcholinsystem erholt. Gedächtnis und Aufmerksamkeit fühlen sich oft auch klarer an.';

  @override
  String get tcaMilestone30Title =>
      'Ein Monat: Autonomes Nervensystem stabilisiert';

  @override
  String get tcaMilestone30Description =>
      'Nach einem Monat beruhigen sich die Körpersysteme, die Herzfrequenz, Blutdruck, Verdauung und Schwitzen kontrollieren. Herzrhythmus- und Blutdruckänderungen bewegen sich in Richtung Normalität, und der REM-Traumschlaf kehrt zurück.';

  @override
  String get tcaMilestone90Title =>
      'Drei Monate: Gehirn-chemische Systeme Settling';

  @override
  String get tcaMilestone90Description =>
      'TCAs beeinflussen mehrere gehirnchemische Systeme. Drei Monate geben ihnen viel Zeit, sich niederzulassen. Stimmung, klares Denken und körperliches Wohlbefinden sind deutlich besser.';

  @override
  String get tcaMilestone180Title => 'Sechs Monate: Herz und Denken Erholung';

  @override
  String get tcaMilestone180Description =>
      'Sechs Monate ermöglichen eine starke Erholung des Herzrhythmus, des Gedächtnisses und der Denkgeschwindigkeit. Die Herz-Rhythmus-Veränderungen und der Gehirnnebel, die durch TCAs verursacht werden, hatten Monate zu lösen.';

  @override
  String get tcaMilestone365Title => 'Ein Jahr: Erholung erreicht';

  @override
  String get tcaMilestone365Description =>
      'Ein Jahr gibt jedem von TCAs betroffenen System ein ganzes Jahr Zeit, um sich zu erholen. Das Acetylcholin-, Noradrenalin-, Serotonin- und Histaminsystem hat sich beruhigt, und Gedächtnis, klares Denken und Herzfrequenzkontrolle sind weitgehend wiederhergestellt.';

  @override
  String get settingsShowTcaTracking => 'TCA-Tracking anzeigen';

  @override
  String get settingsNotifyTca =>
      'Benachrichtigen Sie die TCA, die Fortschritte zu beenden';

  @override
  String get addictionMaoi => 'MAOI';

  @override
  String get maoiPageTitle => 'MAOI-Wiederherstellung';

  @override
  String get maoiHeaderStarted => 'Ihre Recovery Journey';

  @override
  String get maoiHeaderNotStarted => 'Vorteile von Tapering Off MAOIs';

  @override
  String get maoiSubtitleStarted =>
      'Verfolgen Sie Ihre Fortschritte und feiern Sie jeden Meilenstein';

  @override
  String get maoiSubtitleNotStarted =>
      'Sehen Sie, was passiert, wenn Sie sich verjüngen';

  @override
  String get maoiMilestone3Title =>
      'Tag 3: Höchste Risikophase - Medizinische Aufsicht unerlässlich';

  @override
  String get maoiMilestone3Description =>
      'MAOIs tragen die schwerwiegendsten Abbruchrisiken jeder Antidepressivumklasse. Abrupte Einstellung - vor allem von Phenelzin und Tranylcypromin - kann schwere Agitation, Verwirrung, Halluzinationen, Myoklonus und Hyperthermie verursachen. Wenn Sie diese Symptome haben, suchen Sie sofort einen Arzt auf. MAOIs arbeiten, indem sie MAO-Enzyme dauerhaft deaktivieren; Die Erholung erfordert, dass der Körper ein neues Enzym synthetisiert, ein Prozess, der etwa 14 Tage dauert.';

  @override
  String get maoiMilestone7Title => 'Eine Woche: MAO Enzymsynthese im Gange';

  @override
  String get maoiMilestone7Description =>
      'MAOIs zerstören dauerhaft MAO-Enzymmoleküle; die Wiederherstellung erfordert die Synthese völlig neuer Enzyme. Nach einer Woche haben sich möglicherweise etwa 50% der normalen MAO-Aktivität erholt. Schwere akute Abbruchsymptome (Delirium, Myoklonus, Hyperthermie) sind deutlich reduziert. Eine enge medizinische Überwachung bleibt wichtig.';

  @override
  String get maoiMilestone14Title =>
      'Zwei Wochen: MAO-Enzym-Aktivität erheblich wiederhergestellt';

  @override
  String get maoiMilestone14Description =>
      'Zwei Wochen ist der klinische Standardzeitrahmen für die Wiederherstellung des MAO-Enzyms nach Absetzen. Ungefähr am 14. Tag wird die MAO-A- und MAO-B-Aktivität weitgehend wiederhergestellt und der normale Tyraminstoffwechsel wiederhergestellt. Die während der MAOI-Behandlung erforderlichen diätetischen Einschränkungen können in der Regel in Absprache mit Ihrem verschreibenden Arzt gelockert werden.';

  @override
  String get maoiMilestone30Title =>
      'Ein Monat: Brain-Chemical Systems Rebalancing';

  @override
  String get maoiMilestone30Description =>
      'Einen Monat nach dem Absetzen eines MAOI ist das MAO-Enzym wieder aktiv und das Gehirn behandelt Serotonin, Noradrenalin, Dopamin und Tyramin auf natürliche Weise. Die spezielle Nahrungsmittel- und Arzneimittelinteraktionszeit ist beendet, obwohl Sie den Verschreibenden immer noch über die vorherige Verwendung von MAOI informieren sollten.';

  @override
  String get maoiMilestone90Title => 'Drei Monate: Gehirnchemie Normalisierung';

  @override
  String get maoiMilestone90Description =>
      'Drei Monate geben der Stimmung und den Energiesystemen des Gehirns viel Zeit, um sich nach MAOIs anzupassen. Stimmung, Energie und klares Denken stabilisieren sich, da das Gehirn diese Chemikalien wieder auf natürliche Weise behandelt.';

  @override
  String get maoiMilestone180Title => 'Sechs Monate: Langfristige Erholung';

  @override
  String get maoiMilestone180Description =>
      'Sechs Monate stellen eine erhebliche Periode der natürlichen Monoaminfunktion dar. Serotonin-, Noradrenalin- und Dopaminrezeptorpopulationen haben sich normalisiert. Die Phenethylamin-Signalwege (PEA), die ebenfalls von MAOIs betroffen sind, haben sich auf ein natürliches Niveau wiederhergestellt - ein oft übersehener Aspekt der Genesung, der zur emotionalen Normalisierung beiträgt.';

  @override
  String get maoiMilestone365Title => 'Ein Jahr: Erholung erreicht';

  @override
  String get maoiMilestone365Description =>
      'Ein Jahr nach dem Absetzen eines MAOI gibt dem Gehirn und Körper ein ganzes Jahr ohne das Medikament. Stimmung, Energie, klares Denken und normale gehirnchemische Regulierung hatten viel Zeit, sich zu beruhigen und zu erholen.';

